package pipelines

import (
	"encoding/json"
	"math"
	"os"
	"testing"

	"github.com/gomlx/go-huggingface/tokenizers/api"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/knights-analytics/hugot/backends"
)

// decisionFixture is generated by the Python reference (strands-decider's prompt format
// and the exported ONNX graph): rendered texts, token ids, option positions, logits and
// the readout computed from them.
type decisionFixture struct {
	State    json.RawMessage `json:"state"`
	Question struct {
		Kind         string      `json:"kind"`
		Instructions string      `json:"instructions"`
		Options      [][2]string `json:"options"`
	} `json:"question"`
	StateText    string    `json:"state_text"`
	QuestionText string    `json:"question_text"`
	InputIDs     []int64   `json:"input_ids"`
	OptionIndex  []int64   `json:"option_index"`
	Labels       []string  `json:"labels"`
	Logits       []float32 `json:"logits"`
	Expected     struct {
		Probs      []float64 `json:"probs"`
		Noul       *float64  `json:"noul"`
		Score      *float64  `json:"score"`
		Confidence *float64  `json:"confidence"`
	} `json:"expected"`
}

const decisionFixturePath = "../testcases/decisionStrandsDecider.json"

func loadDecisionFixture(t *testing.T) []decisionFixture {
	t.Helper()
	raw, err := os.ReadFile(decisionFixturePath)
	require.NoError(t, err)
	var fx []decisionFixture
	require.NoError(t, json.Unmarshal(raw, &fx))
	require.NotEmpty(t, fx)
	return fx
}

// The fixture's one structured state, as a struct so the key order is the request's.
type decisionTicket struct {
	Ticket  int    `json:"ticket"`
	Subject string `json:"subject"`
	Body    string `json:"body"`
}

func (f decisionFixture) state(t *testing.T) string {
	t.Helper()
	var s string
	if json.Unmarshal(f.State, &s) == nil {
		return s
	}
	var ticket decisionTicket
	require.NoError(t, json.Unmarshal(f.State, &ticket))
	rendered, err := RenderDecisionState(ticket)
	require.NoError(t, err)
	return rendered
}

func (f decisionFixture) question() DecisionQuestion {
	q := DecisionQuestion{Type: DecisionQuestionType(f.Question.Kind), Instructions: f.Question.Instructions}
	for _, o := range f.Question.Options {
		q.Criteria = append(q.Criteria, DecisionCriterion{Name: o[0], Description: o[1]})
	}
	return q
}

func TestDecisionPromptMatchesReference(t *testing.T) {
	for i, f := range loadDecisionFixture(t) {
		assert.Equal(t, f.StateText, renderStrandsState(f.state(t)), "case %d state", i)
		rq, err := renderStrandsQuestion(f.question())
		require.NoError(t, err)
		assert.Equal(t, f.QuestionText, rq.text, "case %d question", i)
		assert.Equal(t, f.Labels, rq.labels, "case %d labels", i)
		for k, span := range rq.spans {
			line := rq.text[span[0]:span[1]]
			assert.Regexp(t, `^\d+\. `, line, "case %d option %d span", i, k)
		}
	}
}

func TestDecisionReadoutMatchesReference(t *testing.T) {
	cfg := DecisionReadoutConfig{
		Temperature:       0.7997762858861774,
		TemperatureByKind: map[string]float64{"noul": 1.0704394404346953, "choice": 0.5608428296613732, "score": 1.4788446944896205},
		OrdinalSmoothing:  0.1,
	}
	for i, f := range loadDecisionFixture(t) {
		rq, err := renderStrandsQuestion(f.question())
		require.NoError(t, err)
		ans, err := readDecision(f.Logits, rq, cfg)
		require.NoError(t, err)
		for k, label := range f.Labels {
			assert.InDelta(t, f.Expected.Probs[k], ans.Probabilities[label], 6e-5, "case %d %s", i, label)
		}
		if f.Expected.Noul != nil {
			assert.InDelta(t, *f.Expected.Noul, ans.Noul, 6e-5)
		}
		if f.Expected.Score != nil {
			assert.InDelta(t, *f.Expected.Score, ans.Score, 6e-5)
		}
		if f.Expected.Confidence != nil {
			assert.InDelta(t, *f.Expected.Confidence, ans.Confidence, 6e-5)
		}
	}
}

// With the model's tokenizer present, the pipeline's encoding must reproduce the
// reference token ids and option positions exactly.
func TestDecisionEncodingMatchesReference(t *testing.T) {
	content, err := os.ReadFile("../models/KnightsAnalytics_strands-decider-onnx/int4/tokenizer.json")
	if err != nil {
		t.Skip("strands-decider tokenizer not present under models/")
	}
	p := &DecisionPipeline{Config: DecisionReadoutConfig{ForceBOS: true, MaxLength: 4096}, bosID: 2}
	p.stateTokenizer, err = newDecisionTokenizer(content, api.EncodeOptions{AddSpecialTokens: true})
	require.NoError(t, err)
	p.questionTokenizer, err = newDecisionTokenizer(content, api.EncodeOptions{IncludeSpans: true})
	require.NoError(t, err)

	fixtures := loadDecisionFixture(t)
	inputs := make([]DecisionInput, len(fixtures))
	for i, f := range fixtures {
		inputs[i] = DecisionInput{State: f.state(t), Questions: map[string]DecisionQuestion{"q": f.question()}}
	}
	rows, err := p.encodeRows(inputs)
	require.NoError(t, err)
	require.Len(t, rows, len(fixtures))
	for _, r := range rows {
		f := fixtures[r.input]
		assert.Equal(t, f.InputIDs, r.ids, "case %d ids", r.input)
		assert.Equal(t, f.OptionIndex, r.options, "case %d option positions", r.input)
	}
}

func TestDecisionQuestionValidation(t *testing.T) {
	bad := []DecisionQuestion{
		{Type: "maybe", Instructions: "?"},
		{Type: DecisionChoice, Instructions: "?", Criteria: []DecisionCriterion{{Name: "only"}}},
		{Type: DecisionChoice, Instructions: "?", Criteria: []DecisionCriterion{{Name: "a"}, {Name: "a"}}},
		{Type: DecisionChoice, Instructions: "?", Criteria: []DecisionCriterion{{Name: "a"}, {Name: "b\nc"}}},
		{Type: DecisionScore, Instructions: "?", Criteria: []DecisionCriterion{{Description: "low"}}},
		{Type: DecisionNoul, Instructions: "?", Criteria: []DecisionCriterion{{Name: "maybe"}}},
	}
	for i, q := range bad {
		_, err := renderStrandsQuestion(q)
		assert.Error(t, err, "case %d", i)
	}
	rq, err := renderStrandsQuestion(DecisionQuestion{
		Type: DecisionNoul, Instructions: "Is it late?",
		Criteria: []DecisionCriterion{{Name: "true", Description: "  after   midnight "}},
	})
	require.NoError(t, err)
	assert.Contains(t, rq.text, "2. true — after midnight\n")
	assert.Contains(t, rq.text, "1. false — the statement does not hold for this state\n")
}

func TestDecisionConfidence(t *testing.T) {
	assert.InDelta(t, 0.0, choiceConfidence([]float64{0.25, 0.25, 0.25, 0.25}), 1e-12)
	assert.InDelta(t, 1.0, choiceConfidence([]float64{0, 1, 0}), 1e-12)
	assert.InDelta(t, 1.0, scoreConfidence([]float64{0, 1, 0}, 0.1), 1e-12)
	assert.InDelta(t, 0.0, scoreConfidence([]float64{0.5, 0, 0.5}, 0), 1e-12)
	assert.False(t, math.IsNaN(scoreConfidence([]float64{1, 0}, 0.5)))
}

func TestDecisionPipelineRequiresORT(t *testing.T) {
	// A model loaded by the Go or XLA backend has no ORT session.
	_, err := NewDecisionPipeline(t.Context(), backends.PipelineConfig[*DecisionPipeline]{Name: "decision"}, &backends.Model{})
	require.Error(t, err)
	assert.Contains(t, err.Error(), "require the ORT backend")
}
